class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        # Track which indices can be marked
        marks = set()
        seconds_needed = 0

        # Go through each second
        for s in range(m):
            # Convert to 0-indexed
            index = changeIndices[s] - 1

            # If the current index isn't marked yet, we may need to decrement here
            if index not in marks:
                if nums[index] > 0:
                    # Count how many seconds are needed to allow marking this index
                    if seconds_needed < nums[index]:
                        seconds_needed = nums[index]

                # Mark the index if nums[index] becomes 0
                if nums[index] == 0:
                    marks.add(index)

            # Decrement relevant indices
            for i in range(n):
                if nums[i] > 0:
                    # Decrement if this index might still be unmarked
                    if i not in marks:
                        nums[i] -= 1

            # Mark the index if it reaches zero now
            if nums[index] == 0:
                marks.add(index)

            # If all indices are already marked, break early
            if len(marks) == n:
                return s + 1

        # After looping through all seconds, check if we managed to mark all indices
        return s + 1 if len(marks) == n else -1
